.cursor {
  background-color: var(--thm-primary-color);
  z-index: 1;
  -webkit-user-select: none;
  user-select: none;
  pointer-events: none;
  z-index: 10000;
  border-radius: 100%;
  width: 6px;
  height: 6px;
  transition: transform .3s cubic-bezier(.75, -1.27, .3, 2.33), opacity .2s cubic-bezier(.75, -.27, .3, 1.33);
  display: none;
  position: fixed;
  transform: scale(1);
}

.cursor:before {
  content: "";
  border: 1px solid var(--thm-primary-color);
  border-radius: 50%;
  position: absolute;
  inset: -7px;
}

.cursor.active, .cursor.menu-active {
  opacity: 1;
  transform: scale(0);
}

.cursor.hovered {
  opacity: 1;
}

.cursor-follower {
  background-color: var(--thm-primary-color);
  opacity: .3;
  z-index: 1;
  -webkit-user-select: none;
  user-select: none;
  pointer-events: none;
  z-index: 10000;
  border-radius: 100%;
  width: 33px;
  height: 33px;
  transition: transform .6s cubic-bezier(.75, -1.27, .3, 2.33), opacity .2s cubic-bezier(.75, -.27, .3, 1.33), background .2s cubic-bezier(.75, -.27, .3, 1.33);
  display: none;
  position: fixed;
  transform: translate(2px, 2px);
}

.cursor-follower.active {
  opacity: .1;
  transform: scale(1.03);
}

.cursor-follower.menu-active {
  opacity: 1;
  transform: scale(3);
}

.cursor-follower.hovered {
  opacity: 1;
}

#ui-datepicker-div.ui-widget-content {
  background: var(--thm-white) none repeat scroll 0 0;
