}

#ui-datepicker-div.ui-datepicker .ui-datepicker-header {
  background: var(--thm-black) none repeat scroll 0 0;
  border: 2px solid var(--thm-primary-color);
  color: var(--thm-white);
  border-radius: 0;
  padding: 5px 0;
  font-weight: 700;
